    from quixote import ptl_compile
    glob = {
        "__file__": _coerceToFilesystemEncoding("", path),
        "resource": resource.ErrorPage(500, "Whoops! Internal Error", rpyNoResource),
        "registry": registry,
    }
    with open(path) as f:
