def _elements_to_dict(data, as_class, tz_aware, uuid_subtype):
    result = as_class()
    position = 0
    end = len(data) - 1
    while position < end:
        (key, value, position) = _element_to_dict(data, position, as_class,
                                                  tz_aware, uuid_subtype)
        result[key] = value
    return result
